+        assertEquals(0, repository.count("ada virtanen", Set.of()));
+        assertEquals(500, repository.count("   ", Set.of()));
+    }
+
+    @Test
+    void nameMatchingIgnoresCaseAndAccents() {
+        List<Long> unaccented = ids(repository.findAll(0, 200, List.of(), "makinen", Set.of()));
+        assertEquals(unaccented, ids(repository.findAll(0, 200, List.of(), "MAKINEN", Set.of())));
+        assertEquals(unaccented, ids(repository.findAll(0, 200, List.of(), "mäkinen", Set.of())));
+
+        List<Long> josephine = ids(repository.findAll(0, 200, List.of(), "josephine", Set.of()));
+        assertTrue(josephine.size() > 0);
+        assertEquals(josephine, ids(repository.findAll(0, 200, List.of(), "Joséphine", Set.of())));
+    }
+
+    @Test
+    void statusAndNameFiltersAreCombinedAndQueriesRemainLogged() {
+        List<Customer> activeAdaAaltonens = repository.findAll(0, 200,
+                List.of(new CustomerSort("id", false)), "ada aal", Set.of(CustomerStatus.ACTIVE));
+
+        assertEquals(List.of(1000L), ids(activeAdaAaltonens));
+        assertEquals(1, repository.count("ada aal", Set.of(CustomerStatus.ACTIVE)));
+        assertEquals(1, queryLog.pageQueries().size());
+        assertEquals(1, queryLog.countQueries().size());
+        assertEquals(1, queryLog.rowsFetched());
+    }
+
+    private static List<Long> ids(List<Customer> customers) {
+        return customers.stream().map(Customer::id).toList();
